/**
 * Re-read the catalogue's Latin names (`name_romaji`) with the current
 * transliteration prompt and model, and report what would change.
 *
 * Why: the names in the mirror were generated by an earlier prompt that gave
 * the model the kanji alone. Checked against 54 names whose reading is
 * printed on a label, 20 were wrong (北鹿 "Kitashika", 花巴 "Hanaba"). The
 * ingest only transliterates a row when it is new or its Japanese name
 * changed, so nothing would ever correct the rows already there.
 *
 * Two steps, so that paying for the model and writing to the database are
 * separate decisions:
 *
 *   pnpm romaji:regenerate                       # says what it would cost, calls nothing
 *   pnpm romaji:regenerate -- --yes              # reads every name, writes a report
 *   pnpm romaji:regenerate -- --apply <report>   # writes the changed names
 *
 * Options: `--kind brand|brewery` (default both), `--limit <n>`,
 * `--model <id>` (default the ingest's), `--out <path>`.
 *
 * A curated reading in `name_romaji_overrides` always wins: the table's
 * trigger sets it on every write, so `--apply` cannot undo one.
 *
 * Requires DATABASE_URL and ANTHROPIC_API_KEY (the npm script loads
 * `.env.local`). The report holds catalogue names only, no personal data;
 * it is gitignored all the same.
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { Pool } from 'pg'
import { getPrefectureNames } from '../src/lib/sakenowa/prefecture'
import { ROMAJI_MODEL, transliterateBatch, type TransliterationItem } from '../src/lib/sakenowa/romaji'
import { romajiKey } from '../src/lib/sakenowa/romaji-key'

/** Measured on 54 names, 2026-10-12: about 640 tokens in and 105 out per name. */
const TOKENS_PER_NAME = { input: 640, output: 105 }
/** US dollars per million tokens, input / output — list prices on 2026-10-12. */
const PRICES: Record<string, [number, number]> = {
  'claude-sonnet-5-5': [2, 10],
  'claude-haiku-5-5': [0.1, 0.5],
}

interface ReportRow {
  kind: 'brand' | 'brewery'
  id: number
  nameKanji: string
  before: string | null
  after: string | null
  /** The two differ by more than spelling (`romajiKey`). */
  changesReading: boolean
  error?: string
}

function arg(name: string): string | undefined {
  const i = process.argv.indexOf(`--${name}`)
  return i === -1 ? undefined : process.argv[i + 1]
}
const flag = (name: string) => process.argv.includes(`--${name}`)

async function apply(pool: Pool, reportPath: string) {
  const rows: ReportRow[] = JSON.parse(readFileSync(reportPath, 'utf8')).rows
  const changed = rows.filter((r) => r.after !== null && r.after !== r.before)
  console.log(`${changed.length} of ${rows.length} names differ from the report's "before" and will be written.`)
  let written = 0
  for (const row of changed) {
    const sql =
      row.kind === 'brand'
        ? 'UPDATE brands SET name_romaji = $1 WHERE brand_id = $2 AND superseded_at IS NULL'
        : 'UPDATE breweries SET name_romaji = $1 WHERE brewery_id = $2 AND superseded_at IS NULL'
    written += (await pool.query(sql, [row.after, row.id])).rowCount ?? 0
  }
  console.log(`Wrote ${written} rows. Curated readings in name_romaji_overrides were kept by their trigger.`)
}

async function main() {
  if (!process.env.DATABASE_URL) throw new Error('DATABASE_URL is not set.')
  const pool = new Pool({ connectionString: process.env.DATABASE_URL })
  try {
    const reportToApply = arg('apply')
    if (reportToApply) return await apply(pool, reportToApply)

    const kind = arg('kind')
    const limit = arg('limit') ? Number(arg('limit')) : undefined
    const model = arg('model') ?? ROMAJI_MODEL
    const out = arg('out') ?? 'romaji-regeneration.json'

    const items: (TransliterationItem & { rowKind: 'brand' | 'brewery'; before: string | null })[] = []
    if (kind !== 'brewery') {
      const { rows } = await pool.query(
        `SELECT br.brand_id AS id, br.name_kanji, br.name_romaji, b.name_kanji AS brewery_kanji, b.area_id
         FROM brands br LEFT JOIN breweries b ON b.brewery_id = br.brewery_id AND b.superseded_at IS NULL
         WHERE br.superseded_at IS NULL AND br.name_kanji <> '' ORDER BY br.brand_id`,
      )
      for (const r of rows) {
        items.push({
          rowKind: 'brand',
          id: r.id,
          nameKanji: r.name_kanji,
          before: r.name_romaji,
          kind: 'sake',
          breweryKanji: r.brewery_kanji ?? undefined,
          prefecture: r.area_id == null ? undefined : getPrefectureNames(r.area_id)?.nameEn,
        })
      }
    }
    if (kind !== 'brand') {
      const { rows } = await pool.query(
        `SELECT brewery_id AS id, name_kanji, name_romaji, area_id FROM breweries
         WHERE superseded_at IS NULL AND name_kanji <> '' ORDER BY brewery_id`,
      )
      for (const r of rows) {
        items.push({
          rowKind: 'brewery',
          id: r.id,
          nameKanji: r.name_kanji,
          before: r.name_romaji,
          kind: 'brewery',
          prefecture: getPrefectureNames(r.area_id)?.nameEn,
        })
      }
    }
    const todo = limit ? items.slice(0, limit) : items

    const [inPrice, outPrice] = PRICES[model] ?? [NaN, NaN]
    const cost = (todo.length * (TOKENS_PER_NAME.input * inPrice + TOKENS_PER_NAME.output * outPrice)) / 1e6
    console.log(`${todo.length} names, model ${model}: about $${cost.toFixed(2)} at list prices.`)
    if (!flag('yes')) {
      console.log('Nothing was called. Add --yes to read the names and write the report.')
      return
    }

    const results = await transliterateBatch(todo, {
      model,
      concurrency: 6,
      onProgress: (done, total) => {
        if (done % 200 === 0 || done === total) console.log(`  ${done}/${total}`)
      },
    })
    const rows: ReportRow[] = todo.map((item, i) => {
      const after = results[i]?.nameRomaji ?? null
      return {
        kind: item.rowKind,
        id: item.id,
        nameKanji: item.nameKanji,
        before: item.before,
        after,
        changesReading: after !== null && (item.before === null || romajiKey(after) !== romajiKey(item.before)),
        ...(results[i]?.error ? { error: results[i].error } : {}),
      }
    })
    writeFileSync(out, `${JSON.stringify({ generatedAt: new Date().toISOString(), model, rows }, null, 1)}\n`)

    const failed = rows.filter((r) => r.after === null).length
    const reading = rows.filter((r) => r.changesReading).length
    const spelling = rows.filter((r) => r.after !== null && r.after !== r.before && !r.changesReading).length
    console.log(`Report: ${out}`)
    console.log(`  ${reading} names would change their reading, ${spelling} only their spelling, ${failed} failed.`)
    console.log(`Read the report, then: pnpm romaji:regenerate -- --apply ${out}`)
  } finally {
    await pool.end()
  }
}

main().catch((err) => {
  console.error('romaji-regenerate: fatal error', err)
  process.exit(1)
})
